import re


_COLOR_TERMS = (
    "light-gray-and-ivory", "medium-dark vintage-blue", "navy-and-cream", "red-and-white",
    "black-and-white", "muted sage-green", "light-vintage-blue", "soft-powder-blue",
    "medium-wash", "royal-blue", "light-pink", "light-wash", "medium-blue", "deep-red",
    "off-white", "light-blue", "dark-brown", "sky-blue", "light-gray", "dark-indigo",
    "dusty-teal", "charcoal-gray", "chocolate-brown", "mint-green", "dusty-blue",
    "forest-green", "bright-red", "olive-green", "light-stone", "ice-white", "dark-red",
    "pastel-pink", "soft-ivory", "vanilla-cream", "warm-ivory", "light-beige", "crisp-white",
    "warm-beige", "pure-white", "vivid-cobalt", "soft-white", "deep-navy", "bright-white",
    "bright-aqua", "charcoal-black", "soft-cream", "washed-black", "soft-beige",
    "light-sky-blue", "espresso-brown", "dark-chocolate", "powder-blue", "soft-blush",
    "clean-white", "vintage-blue", "matte-black", "black", "pink", "white", "charcoal", "brown", "olive",
    "ice-blue", "ivory", "gray", "cream", "red", "taupe", "blue", "lavender", "silver",
)

_COLOR_PATTERN = re.compile(
    r"(?<![\w-])(?:" + "|".join(re.escape(color) for color in sorted(_COLOR_TERMS, key=len, reverse=True)) + r")(?![\w-])\s*",
    re.IGNORECASE,
)


def _remove_explicit_colors(theme):
    return " ".join(_COLOR_PATTERN.sub("", theme).split())


ZHANG_RUONAN_COLOR_FREE_THEMES = [
    _remove_explicit_colors(theme)
    for theme in ZHANG_RUONAN_ORIGINAL_COLOR_THEMES
]

ZHANG_RUONAN_COLOR_FREE_THEMES = [
    theme
    .replace("an tiered", "a tiered")
    .replace("deep sleeveless knit vest", "sleeveless knit vest")
    .replace("a oversized", "an oversized")
    for theme in ZHANG_RUONAN_COLOR_FREE_THEMES
]
